insert into iam_role_capability(role_id,capability_code) select '00000000-0000-0000-0000-000000000001'::uuid,x from unnest(array['analytics.read','audit.read','identity.manage','policy.manage']) x;
insert into iam_role_capability(role_id,capability_code) select r.id,x from iam_role r cross join lateral unnest(case r.code when 'R02' then array['analytics.read','audit.read','integration.manage','integration.reconcile'] when 'R03' then array['analytics.export','analytics.read','audit.read','housekeeping.manage','maintenance.manage','requisition.manage'] when 'R04' then array['analytics.read','inventory.count','inventory.move','inventory.read','inventory.reserve','requisition.manage'] when 'R05' then array['inventory.move','inventory.read','inventory.reserve','requisition.manage'] when 'R06' then array['analytics.read','inventory.read','purchase.order.issue','purchase.request','purchase.source'] when 'R07' then array['analytics.read','audit.read','purchase.approve'] when 'R08' then array['analytics.read','inventory.read','receiving.execute'] when 'R09' then array['analytics.read','inventory.read','production.plan'] when 'R10' then array['inventory.read','production.execute'] when 'R11' then array['analytics.read','inventory.read','inventory.reserve','maintenance.manage'] when 'R12' then array['inventory.read','inventory.reserve','maintenance.execute'] when 'R13' then array['analytics.read','housekeeping.manage','maintenance.manage'] when 'R14' then array['housekeeping.execute'] when 'R15' then array['inventory.count'] when 'R16' then array['audit.read','inventory.adjust.approve','inventory.read'] when 'R17' then array['analytics.export','analytics.read'] when 'R18' then array['analytics.export','analytics.read','audit.read'] when 'R19' then array['analytics.read'] when 'R20' then array['analytics.read'] else array[]::text[] end) x;
